public class Complex_divide_TriageGen2Test {

    private static final double DELTA = 1e-10;

    @Test
    public void testDivide_NaN_InputIsNaN() {
        // Testing if(isNaN || Double.isNaN(divisor))
        Complex c = Complex.NaN;
        Complex result = c.divide(1.0);
        Assert.assertTrue("Result should be NaN when input complex is NaN", result.isNaN());
    }

    @Test
    public void testDivide_DivisorIsNaN() {
        // Testing if(isNaN || Double.isNaN(divisor))
        Complex c = new Complex(1.0, 1.0);
        Complex result = c.divide(Double.NaN);
        Assert.assertTrue("Result should be NaN when divisor is NaN", result.isNaN());
    }

    @Test
    public void testDivide_DivisorIsZero() {
        // Testing if(divisor == 0d)
        Complex c = new Complex(1.0, 1.0);
        Complex result = c.divide(0.0);
        Assert.assertTrue("Result should be NaN when divisor is 0.0", result.isNaN());
    }

    @Test
    public void testDivide_InfiniteComplex_NotInfinite() {
        // Note: The provided source code contains a logic flaw: 'if (true) { return !isInfinite() ? ZERO : NaN; }'
        // This block makes the rest of the method unreachable. 
        // To maximize coverage of the provided snippet, we test the logic inside 'if (true)'.

        // Case 1: Complex is NOT infinite -> returns ZERO
        Complex c = new Complex(1.0, 1.0);
        Complex result = c.divide(2.0);
        Assert.assertEquals(0.0, result.getReal(), DELTA);
        Assert.assertEquals(0.0, result.getImaginary(), DELTA);
        Assert.assertFalse(result.isNaN());
    }

    @Test
    public void testDivide_InfiniteComplex_IsInfinite() {
        // Case 2: Complex IS infinite -> returns NaN
        Complex c = new Complex(Double.POSITIVE_INFINITY, 1.0);
        Complex result = c.divide(2.0);
        Assert.assertTrue("Result should be NaN when complex is infinite", result.isNaN());
    }

